#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public Queue_PRS  {  CShForsunka sh;  bool bFirePilot;  bool bSocket;  bool bFireMain;  } Queue_ForsST;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintForsST(DefinePaint)  {  QueueP(Queue_ForsST);  //  CShForsunka& sh = (CShForsunka&)PipeSH;  if ( IsTypeOK )    if ( !p->m_bPressed )      {      memcpy( &p->sh, &sh, sizeof( p->sh ) );      p->bFirePilot = (p->sh.State_Flags & CForsunka::IS_ZAPAL_FIRE) != 0;	  p->bFireMain= p->sh.Is_State(CForsunka::IS_WORK_FIRE);      }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция посылки сообщенияstatic void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_ForsST* p = (Queue_ForsST*)base;  if ( !ISTypeOK ) return;  //  bool bSend = true;  //  //if ( lstrcmp( p->send.szValue, "Зажигание" ) == 0 )  //  {  //  //if (obj->setFire != setFire && obj->isFire != setFire)  //  //obj->setFire = setFire;  //  bSend = p->sh.canFire != 0;  //  }  //  if ( lstrcmp( p->send.szValue, "Зажигание_Пилот" ) == 0 )    {    //if (obj->setFire != setFire && obj->isFire != setFire)    //obj->setFire = setFire;    bSend = false;    bool bNew = true;    p->send.SetNew( &bNew );    p->pPipe->SendData( p->send, bMessage );    }  //  if ( bSend )    {    p->send.SetNew( pVoid );    p->pPipe->SendData( p->send, bMessage );    }  p->m_bPressed = !bMessage;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void FillFors( SPriborBase* d, void* pp )  {  d->fnData = fnSendData;  Queue_ForsST* p = (Queue_ForsST*)pp;  if ( d->pVoid == &p->sh.State_Flags && lstrcmp( p->send.szValue, "Зажигание_Пилот" ) == 0 )       d->pVoid =  &p->bFirePilot;  if ( d->pVoid == &p->sh.State_Flags && lstrcmp( p->send.szValue, "ОсновнойГорит" ) == 0 )       d->pVoid =  &p->bFireMain;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddForsST(DefineTegs)  {  //  AddQueueEx(Queue_ForsST);  //  CShForsunka sh;  memcpy( &p->sh, &sh, sizeof(CShForsunka) );  p->pSH = &p->sh;  //  p->bSocket=false;  p->bFireMain=false;  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintForsST;      STegObj obj[] =    {	{ 'L', "socket", &p->bSocket },    // Дополнительная информация    EXT_QUEUE    };::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  	if (p->bSocket)		AddPribors( def, teg, Buffer, p, &FillFors, id_Forsunka );	else		AddPriborsPipe( def, teg, Buffer, p, &FillFors, id_Forsunka );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~